import { createServer } from "node:http";
//#region src/test_utils/neon_api_server.ts
const startNeonApiServer = async (user = {
	id: "user-1",
	email: "user@example.com"
}) => {
	const rejected = /* @__PURE__ */ new Set();
	const seen = [];
	let rejectAll = false;
	let failUserLookup = false;
	const server = createServer((req, res) => {
		const url = new URL(req.url ?? "/", `http://${req.headers.host}`);
		const token = (req.headers.authorization ?? "").replace(/^Bearer\s+/i, "");
		if (url.pathname !== "/users/me") return json(res, 404, { message: "Not Found" });
		seen.push(token);
		if (rejectAll || token === "" || rejected.has(token)) return json(res, 401, { message: "Unauthorized" });
		if (failUserLookup) return json(res, 500, { message: "Internal Server Error" });
		return json(res, 200, {
			id: user.id,
			email: user.email,
			login: "tester",
			name: "Tester",
			projects_limit: 10,
			branches_limit: 10,
			max_autoscaling_limit: 1,
			plan: "free",
			auth_accounts: []
		});
	});
	await new Promise((resolve) => {
		server.listen(0, "127.0.0.1", resolve);
	});
	return {
		url: `http://127.0.0.1:${server.address().port}`,
		reject: (accessToken) => {
			rejected.add(accessToken);
		},
		rejectAll: (value) => {
			rejectAll = value;
		},
		failUserLookup: (value) => {
			failUserLookup = value;
		},
		seenTokens: () => [...seen],
		stop: () => closeServer(server)
	};
};
const json = (res, status, body) => {
	const payload = JSON.stringify(body);
	res.writeHead(status, {
		"content-type": "application/json",
		"content-length": Buffer.byteLength(payload)
	});
	res.end(payload);
};
const closeServer = (server) => new Promise((resolve, reject) => {
	server.close((err) => err ? reject(err) : resolve());
});
//#endregion
export { startNeonApiServer };
